-- 来料质量域扩充：IQC 来料批次明细补充 + 来料上线不良事实表
-- 幂等：CREATE TABLE IF NOT EXISTS + INSERT OR IGNORE + 显式 id
-- 生成：脚本一次性产出（随机种子固定，可复现）
-- ============================================================

-- 覆盖 2026-10-01 ~ 2026-10-15，支撑「来料批次不良 / 来料上线不良率」的**固定全量口径**
-- （不受板级统计口径与工段/类别筛选影响，见 services/dashboard.py 的 INCOMING_WINDOW）。
-- 纪律：供应商**沿用既有 41 家**（不新增供应商，避免破坏既有「全集匹配」断言）；
--       新表 incoming_line_defect 仅供来料上线不良率聚合，不并入 quality_defect 口径。
-- 新增行数：来料上线不良 515 条 + IQC 批次明细 394 条

CREATE TABLE IF NOT EXISTS incoming_line_defect (
  id INTEGER PRIMARY KEY,
  inspect_date TEXT,        -- 上线检验日期
  supplier TEXT,            -- 供应商
  part_no TEXT,             -- 料号
  part_name TEXT,           -- 物料名称
  batch_no TEXT,            -- 来料批次
  line_code TEXT,           -- 上线产线
  product_model TEXT,       -- 型号
  defect_type TEXT,         -- 上线不良模式
  defect_qty INTEGER DEFAULT 0,   -- 上线不良数
  total_qty INTEGER DEFAULT 0,    -- 上线投入数
  disposition TEXT,         -- 处置结论（退货 / 特采 / 挑选返工 / 供应商改善）
  owner TEXT                -- 责任人
);

INSERT OR IGNORE INTO incoming_line_defect
  (id, inspect_date, supplier, part_no, part_name, batch_no, line_code,
   product_model, defect_type, defect_qty, total_qty, disposition, owner) VALUES
